from normalize import normalize

def replay(capacity, events):
    state = {"active": {}, "reserved": 0, "releases": 0}
    for event in normalize(events):
        key = event["id"]
        if event["kind"] == "reserve":
            units = event["units"]
            state["active"][key] = units
            state["reserved"] += units
        else:
            previous = state["active"].pop(key, None)
            if previous is not None:
                state["reserved"] -= previous
                state["releases"] += 1
    return {"available": capacity - state["reserved"], "active": state["active"], "releases": state["releases"]}

def normalize(events):
    result = []
    for event in events:
        kind = event["kind"]
        if kind not in ("reserve", "release"):
            raise ValueError("unsupported event")
        amount = int(event.get("units", 0))
        if amount < 0:
            raise ValueError("negative units")
        result.append({"kind": kind, "id": str(event["id"]), "units": amount})
    return result

def normalized_count(events):
    return len(normalize(events))

